#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

API_BASE="${RENT_API_BASE:-}"
if [[ -z "$API_BASE" ]]; then
  echo "ERROR: Set RENT_API_BASE to the public HTTPS URL of the Render bot/API Web Service." >&2
  exit 1
fi
if [[ "$API_BASE" != https://* ]]; then
  echo "ERROR: RENT_API_BASE must start with https://" >&2
  exit 1
fi
API_BASE="${API_BASE%/}"

cat > js/config.js <<EOF
/* Generated by render-build.sh. Do not edit in the Render build output. */
window.RENT_API_ENABLED = true;
window.RENT_API_BASE = "${API_BASE}";
EOF

echo "Website configured to use RENT API: ${API_BASE}"
